def count_divisible_permutations(n: int) -> int:
    dp = [0] * (1 << n)
    dp[0] = 1
    for mask in range(1 << n):
        if not dp[mask]:
            continue
        i = bin(mask).count('1') + 1
        if i > n:
            continue
        for v in range(1, n + 1):
            bit = 1 << (v - 1)
            if not mask & bit and (v % i == 0 or i % v == 0):
                dp[mask | bit] += dp[mask]
    return dp[(1 << n) - 1]
